import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.ts";

const R = 6371000;
describe("tiltGlobeCamera", () => {
    it("tilts a fresh (fully zoomed-out) camera and keeps radius/yaw/center", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        const r0 = cam.radius, y0 = cam.yaw, c0 = { ...cam.center };
        for (const p of [0.1, 0.6, 1.2]) {
            const cam2 = createGeospatialCamera({ planetRadius: R });
            setGeospatialOrientation(cam2, { yaw: 0.7, center: { x: R, y: 0, z: 0 } });
            const rr = cam2.radius, yy = cam2.yaw;
            tiltGlobeCamera(cam2, p);
            expect(cam2.pitch).toBeCloseTo(p, 9);
            expect(cam2.radius).toBe(rr);
            expect(cam2.yaw).toBeCloseTo(yy, 9);
            expect(cam2.center.x).toBeCloseTo(R, 3);
            // lookAt passes through center: center - position is radius * lookAt
            const d = [cam2.center.x - cam2.position.x, cam2.center.y - cam2.position.y, cam2.center.z - cam2.position.z];
            const len = Math.hypot(...d);
            expect(len).toBeCloseTo(cam2.radius, 3);
            // angle between view dir and geocentric up equals pitch
            const up = [cam2.center.x / R, cam2.center.y / R, cam2.center.z / R];
            const cosA = (d[0]! * up[0]! + d[1]! * up[1]! + d[2]! * up[2]!) / len;
            expect(Math.acos(-cosA)).toBeCloseTo(p, 6);
        }
        tiltGlobeCamera(cam, 0.8);
        expect(cam.pitch).toBeCloseTo(0.8, 9);
        expect(cam.radius).toBe(r0);
        expect(cam.yaw).toBeCloseTo(y0, 9);
        expect(cam.center).toEqual(c0);
    });
    it("stays at tilt when zoomed in and out afterwards", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        tiltGlobeCamera(cam, 1.0);
        for (const r of [R * 3, R * 1.5, R * 0.5, R * 2.5, R * 4]) {
            setGeospatialOrientation(cam, { radius: r });
            expect(cam.pitch).toBeCloseTo(1.0, 9);
        }
    });
});
